import React from "react";

export const getTableChildren = (children: React.ReactNode) => {
  const toolbar = React.Children.toArray(children).find(
    (child) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string }).displayName === "Table.Toolbar",
  );
  const header = React.Children.toArray(children).find(
    (child) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string }).displayName === "Table.Header",
  );
  const body = React.Children.toArray(children).find(
    (child) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string }).displayName === "Table.Body",
  );
  const footer = React.Children.toArray(children).find(
    (child) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string }).displayName === "Table.Footer",
  );

  const filterChipBars = React.Children.toArray(children).find(
    (child) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string }).displayName === "Table.FilterChipBars",
  );

  const emptyState = React.Children.toArray(children).find(
    (child) =>
      React.isValidElement(child) &&
      (child.type as { displayName?: string }).displayName === "Table.EmptyState",
  );

  return {
    toolbar,
    header,
    body,
    footer,
    filterChipBars,
    emptyState,
  };
};
